const $=s=>document.querySelector(s);
async function pixels(a){const img=new Image();await new Promise((yes,no)=>{img.onload=yes;img.onerror=()=>no(Error('Could not load '+a.name));img.src=a.data||a.src;});const c=document.createElement('canvas');c.width=a.width;c.height=a.height;c.getContext('2d').drawImage(img,0,0);const data=c.getContext('2d').getImageData(0,0,c.width,c.height).data;c.width=c.height=1;return{width:a.width,height:a.height,pixels:data};}
